def gen(rng):
    def fmt(js):
        return str(len(js)) + '\n' + '\n'.join(f'{a} {b}' for a, b in js) + '\n'
    tests = [
        fmt([(1, 1)]), fmt([(5, 3)]), fmt([(3, 5), (3, 5)]), fmt([(2, 2), (2, 2), (2, 2)]),
        fmt([(10**9, 10**9)] * 3), fmt([(1, 10**9), (10**9, 1)]), fmt([(4, 1), (4, 1), (4, 1), (4, 1)]),
        fmt([(1, 9), (1, 9), (1, 9)]), fmt([(3, 6), (8, 2), (5, 5), (2, 7), (9, 4)]),
    ]
    for n in (2, 3, 4, 5, 6, 7):
        for hi in (3, 8, 30):
            for _ in range(3):
                tests.append(fmt([(rng.randint(1, hi), rng.randint(1, hi)) for _ in range(n)]))
    for n in (100, 300):
        tests.append(fmt([(rng.randint(1, 10**6), rng.randint(1, 10**6)) for _ in range(n)]))
    N = 100000
    tests.append(fmt([(rng.randint(1, 10**9), rng.randint(1, 10**9)) for _ in range(N)]))
    tests.append(fmt([(rng.randint(1, 10**9), rng.randint(1, 10**9)) for _ in range(N)]))
    tests.append(fmt([(rng.randint(1, 1000), rng.randint(1000, 10**9)) for _ in range(N)]))
    tests.append(fmt([(rng.randint(1000, 10**9), rng.randint(1, 1000)) for _ in range(N)]))
    tests.append(fmt([(10**9, 10**9)] * N))
    return tests
